select
,
tlf.mid_finish_qty,
tlf.night_finish_qty,
tlf.day_finish_qty,
trt.recipe_type_name,
CASE WHEN tlf.mid_finish_qty != 0 THEN TRUNCATE(a.mid_plan_qty/tlf.mid_finish_qty, 4) ELSE null END MID_FINISH_RATE,
CASE WHEN tlf.night_finish_qty != 0 THEN TRUNCATE(a.night_plan_qty/tlf.night_finish_qty, 4) ELSE null END NIGHT_FINISH_RATE,
CASE WHEN tlf.day_finish_qty != 0 THEN TRUNCATE(a.day_plan_qty/tlf.day_finish_qty, 4) ELSE null END DAY_FINISH_RATE
from t_material_schedule_result a
left join t_lhfl_finish tlf on a.order_no = tlf.order_no and tlf.del_flag = 0
left join t_recipe_type trt on a.recipe_type = trt.recipe_type_code and trt.del_flag = 0
where a.del_flag = '0'
and a.schedule_date = #{scheduleDate}
and a.machine_code = #{machineCode}
and a.mix_area = #{mixArea}
and INSTR(a.material_name, #{materialName}) > 0
and a.release_status = #{releaseStatus}
and a.publish_success_count > 0
and a.newest_publish_time = #{newestPublishTime}
and a.data_source = #{dataSource}

    order by machine_code, a.mid_produce_order


    order by machine_code, ${orderStr}

WITH temp_table AS (
SELECT #{rowNumber} row_numbers, #{data.scheduleDate} schedule_date, #{data.materialName} material_name, #{data.machineCode} machine_code FROM dual
) select #{importLogId} importLogId, t.row_numbers errorRow, #{errorDetail} errorDetail, #{createBy} createBy, now() createTime from t_material_schedule_result m inner join temp_table t on m.schedule_date = t.schedule_date AND m.material_name = t.material_name AND m.machine_code = t.machine_code and m.del_flag ='0'

