SELECT #{data.id} id, #{data.scheduleDate} schedule_date, #{data.materialName} material_name, #{data.machineCode} machine_code FROM dual
) select m.id, m.schedule_date, m.machine_code, m.material_name from t_material_schedule_result m inner join temp_table t on m.schedule_date = t.schedule_date and m.material_name = t.material_name and m.machine_code = t.machine_code and m.del_flag ='0' and m.id != t.id

